class ForwardingResource(Resource):
    """forwarding: retrieve, update."""

    def retrieve(
        self,
        *,
        timeout: Optional[float] = None,
        max_retries: Optional[int] = None,
    ) -> t.Forwarding:
        """Retrieve your forwarding rules

        Your forwarding rules, one per asset you forward.

        GET /forwarding
        """
        return cast(
            "t.Forwarding",
            self._request(
                "GET",
                "/forwarding",
                timeout=timeout,
                max_retries=max_retries,
            ),
        )

    def update(
        self,
        *,
        rules: List[t.ForwardingRule],
        object: Optional[Literal["forwarding"]] = None,
        timeout: Optional[float] = None,
        max_retries: Optional[int] = None,
    ) -> t.Forwarding:
        """Set your forwarding rules

        Replaces your forwarding rules with these, all at once (an empty list stops
        forwarding). A rule forwards an asset to one of your active destinations: in
        `payment` mode each payment's credit as it reaches your available balance, in
        `daily` mode your whole available balance once a day at `hour` UTC. Nothing under
        `min_amount` is forwarded. Forwarding payouts are ordinary payouts with
        `source: forwarding`; the network fee comes out of them (`fee_paid_by: payee`).

        PUT /forwarding
        """
        return cast(
            "t.Forwarding",
            self._request(
                "PUT",
                "/forwarding",
                body={
                    "object": object,
                    "rules": rules,
                },
                amounts=("/rules/*/min_amount",),
                timeout=timeout,
                max_retries=max_retries,
            ),
        )


